function validate(input) {
  const [{ Point2D = [] }] = input;
  if (Point2D.length < 2) return 'Point2D needs at least two points.';
  const seen = new Set();
  for (const [x, y] of Point2D) {
    if (x === null || y === null) return 'Every point needs both x and y.';
    const key = `${x},${y}`;
    if (seen.has(key)) return `Point (${key}) appears twice.`;
    seen.add(key);
  }
  return null;
}

