function generate(rand, size) {
  const small = size === 'small';
  const count = small ? 2 + Math.floor(rand() * 7) : 800;
  const range = small ? 3 : 10000;
  const seen = new Set(), Point2D = [];
  while (Point2D.length < count) {
    const x = Math.floor(rand() * (2 * range + 1)) - range, y = Math.floor(rand() * (2 * range + 1)) - range;
    if (seen.has(`${x},${y}`)) continue;
    seen.add(`${x},${y}`);
    Point2D.push([x, y]);
  }
  return [{ Point2D }];
}
